using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Net;using System.Net.Http;using System.Net.Http.Headers;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using System.Threading;
namespace Iris {
    public interface ISpotifyApi {Dictionary<string,object> Request(string method,string path,object body,CancellationToken token);}
    public sealed class SpotifyApi : ISpotifyApi {
        static readonly SemaphoreSlim refreshGate=new SemaphoreSlim(1,1),loginGate=new SemaphoreSlim(1,1);
        static readonly HttpClient http=CreateHttp();readonly string directory;
        public const string Redirect="http://127.0.0.1:43871/callback";
        static HttpClient CreateHttp(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;return new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(15),MaxResponseContentBufferSize=1024*1024};}
        public SpotifyApi(string directory){this.directory=directory;}
        public static string Challenge(string verifier){using(var sha=SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(Encoding.ASCII.GetBytes(verifier))).TrimEnd('=').Replace('+','-').Replace('/','_');}
        static string Random(){var bytes=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(bytes);return Convert.ToBase64String(bytes).TrimEnd('=').Replace('+','-').Replace('/','_');}
        static Dictionary<string,object> Token(IDictionary<string,string> fields,CancellationToken token){using(var request=new HttpRequestMessage(HttpMethod.Post,"https://accounts.spotify.com/api/token")){request.Content=new FormUrlEncodedContent(fields);using(var response=http.SendAsync(request,token).GetAwaiter().GetResult()){if(!response.IsSuccessStatusCode)throw new InvalidOperationException(L.T("Spotify-Anmeldung abgelehnt (HTTP ")+(int)response.StatusCode+L.T("). Erneut verbinden; Client-ID, Freigabe und Redirect prüfen."));return IntegrationJson.Parse(response.Content.ReadAsStringAsync().GetAwaiter().GetResult());}}}
        void SaveTokens(Dictionary<string,object> tokens,string client,string previousRefresh){string access=IntegrationJson.Text(tokens,"access_token"),refresh=IntegrationJson.Text(tokens,"refresh_token");if(access.Length==0)throw new InvalidDataException(L.T("Spotify hat kein Zugriffstoken geliefert."));AddonConnectionStore.Update(directory,c=>{if(c.SpotifyClientId!=client||c.SpotifyRefresh!=previousRefresh)throw new InvalidOperationException(L.T("Verbindung wurde zwischenzeitlich geändert. Erneut anmelden."));c.SpotifyAccess=access;c.SpotifyRefresh=refresh.Length>0?refresh:previousRefresh;c.SpotifyExpires=DateTime.UtcNow.AddSeconds(Math.Max(30,IntegrationJson.Number(tokens,"expires_in"))-20);});}
        public void Connect(Action<string> open,CancellationToken token){if(!loginGate.Wait(0))throw new InvalidOperationException(L.T("Eine Spotify-Anmeldung läuft bereits."));try{var settings=AddonConnectionStore.Read(directory);if(string.IsNullOrEmpty(settings.SpotifyClientId))throw new InvalidOperationException(L.T("Unter Add-ons → Verbindungen zuerst die Spotify-Client-ID eintragen."));string state=Random(),verifier=Random()+Random();var listener=new TcpListener(IPAddress.Loopback,43871);try{listener.Start(4);}catch{throw new InvalidOperationException(L.T("Lokaler Anmeldeport 43871 ist belegt. Andere Anmeldung beenden und erneut versuchen."));}using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(TimeSpan.FromMinutes(3));try{string uri="https://accounts.spotify.com/authorize?response_type=code&client_id="+Uri.EscapeDataString(settings.SpotifyClientId)+"&redirect_uri="+Uri.EscapeDataString(Redirect)+"&scope="+Uri.EscapeDataString("user-read-playback-state user-modify-playback-state user-library-modify")+"&state="+state+"&code_challenge_method=S256&code_challenge="+Challenge(verifier);open(uri);string code=null;using(timeout.Token.Register(listener.Stop)){for(int n=0;n<20&&code==null;n++){TcpClient client;try{client=listener.AcceptTcpClientAsync().GetAwaiter().GetResult();}catch{timeout.Token.ThrowIfCancellationRequested();throw;}using(client){client.ReceiveTimeout=2500;client.SendTimeout=2500;using(var stream=client.GetStream()){var bytes=new List<byte>();while(bytes.Count<8192){int b=stream.ReadByte();if(b<0)break;bytes.Add((byte)b);int l=bytes.Count;if(l>=4&&bytes[l-4]==13&&bytes[l-3]==10&&bytes[l-2]==13&&bytes[l-1]==10)break;}string line=Encoding.ASCII.GetString(bytes.ToArray()).Split('\r')[0];string[] parts=line.Split(' ');Uri callback;bool valid=parts.Length==3&&parts[0]=="GET"&&parts[1].StartsWith("/callback?",StringComparison.Ordinal)&&Uri.TryCreate("http://127.0.0.1:43871"+parts[1],UriKind.Absolute,out callback);var query=valid?System.Web.HttpUtility.ParseQueryString(new Uri("http://127.0.0.1:43871"+parts[1]).Query):null;valid=valid&&query["state"]==state;string page=valid?L.T("Iris: Anmeldung empfangen. Du kannst dieses Fenster schliessen."):L.T("Iris: ungueltige Anmeldung.");var body=Encoding.UTF8.GetBytes(page);var header=Encoding.ASCII.GetBytes("HTTP/1.1 "+(valid?"200 OK":"400 Bad Request")+"\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(body,0,body.Length);if(valid){if(!string.IsNullOrEmpty(query["error"]))throw new InvalidOperationException(L.T("Spotify-Anmeldung abgebrochen oder nicht freigegeben."));code=query["code"];if(string.IsNullOrEmpty(code)||code.Length>4096)throw new InvalidDataException(L.T("Ungültige Spotify-Antwort."));}}}}}timeout.Token.ThrowIfCancellationRequested();if(code==null)throw new InvalidOperationException(L.T("Keine gültige Spotify-Anmeldung empfangen."));var tokens=Token(new Dictionary<string,string>{{"grant_type","authorization_code"},{"code",code},{"redirect_uri",Redirect},{"client_id",settings.SpotifyClientId},{"code_verifier",verifier}},timeout.Token);SaveTokens(tokens,settings.SpotifyClientId,settings.SpotifyRefresh);}finally{listener.Stop();}}}finally{loginGate.Release();}}
        string Access(CancellationToken token,bool force){refreshGate.Wait(token);try{var c=AddonConnectionStore.Read(directory);if(c.SpotifyRefresh.Length==0)throw new InvalidOperationException(L.T("Spotify ist nicht verbunden. Die Aktion „Spotify verbinden“ verwenden."));if(!force&&c.SpotifyAccess.Length>0&&DateTime.UtcNow<c.SpotifyExpires)return c.SpotifyAccess;var tokens=Token(new Dictionary<string,string>{{"grant_type","refresh_token"},{"refresh_token",c.SpotifyRefresh},{"client_id",c.SpotifyClientId}},token);SaveTokens(tokens,c.SpotifyClientId,c.SpotifyRefresh);return IntegrationJson.Text(tokens,"access_token");}finally{refreshGate.Release();}}
        public Dictionary<string,object> Request(string method,string path,object body,CancellationToken token){if(!path.StartsWith("/me/",StringComparison.Ordinal))throw new InvalidOperationException(L.T("Ungültiger Spotify-API-Pfad."));for(int attempt=0;attempt<2;attempt++){using(var request=new HttpRequestMessage(new HttpMethod(method),"https://api.spotify.com/v1"+path)){request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",Access(token,attempt>0));if(body!=null)request.Content=new StringContent(IntegrationJson.Stringify(body),Encoding.UTF8,"application/json");using(var response=http.SendAsync(request,token).GetAwaiter().GetResult()){int status=(int)response.StatusCode;if(status==401&&attempt==0)continue;if(status==204)return new Dictionary<string,object>();if(!response.IsSuccessStatusCode)throw new InvalidOperationException(status==403?L.T("Spotify verweigert diese Funktion. Premium, freigegebenes Konto und API-Berechtigungen prüfen."):status==404?L.T("Spotify: kein aktives Connect-Gerät. Wiedergabe zuerst in Spotify starten."):status==429?L.T("Spotify-Anfragelimit erreicht. Später erneut versuchen."):L.T("Spotify-Anfrage fehlgeschlagen (HTTP ")+status+").");string json=response.Content.ReadAsStringAsync().GetAwaiter().GetResult();return string.IsNullOrWhiteSpace(json)?new Dictionary<string,object>():IntegrationJson.Parse(json);}}}throw new InvalidOperationException(L.T("Spotify-Anmeldung ist abgelaufen."));}
    }
    public static class SpotifyActions {
        public static AddonResult Execute(ISpotifyApi api,AddonAction action,CancellationToken token){string op=action.Kind.Substring(8);if(op=="devices"){var devices=IntegrationJson.Array(api.Request("GET","/me/player/devices",null,token),"devices");return AddonResult.Of(AddonResultCode.Succeeded,devices.Length==0?L.T("Keine Connect-Geräte verfügbar. Spotify auf dem gewünschten Gerät öffnen."):string.Join("\n\n",devices.Select(d=>IntegrationJson.Text(d,"name")+" · "+IntegrationJson.Text(d,"type")+(IntegrationJson.Bool(d,"is_active")?L.T(" · aktiv"):"")+"\nID: "+IntegrationJson.Text(d,"id"))));}
            if(op=="device"){api.Request("PUT","/me/player",new{device_ids=new[]{action.Target},play=false},token);return AddonResult.Of(AddonResultCode.Succeeded,L.T("Gerätewechsel von Spotify angenommen; Wiedergabe nicht automatisch gestartet."));}
            if(op=="play-context"){api.Request("PUT","/me/player/play",new{context_uri=action.Target},token);return AddonResult.Of(AddonResultCode.Succeeded,L.T("Playlist-/Albumwiedergabe von Spotify angenommen."));}
            var state=api.Request("GET","/me/player",null,token);if(state.Count==0)throw new InvalidOperationException(L.T("Keine aktive Spotify-Wiedergabe gefunden."));
            if(op=="api-shuffle"){bool next=!IntegrationJson.Bool(state,"shuffle_state");api.Request("PUT","/me/player/shuffle?state="+(next?"true":"false"),null,token);var read=api.Request("GET","/me/player",null,token);return AddonResult.State("Shuffle: "+(IntegrationJson.Bool(read,"shuffle_state")?L.T("an"):L.T("aus")),L.T("Shuffle gelesen"));}
            if(op=="api-repeat"){string before=IntegrationJson.Text(state,"repeat_state"),next=before=="off"?"context":before=="context"?"track":"off";api.Request("PUT","/me/player/repeat?state="+next,null,token);var read=api.Request("GET","/me/player",null,token);return AddonResult.State(L.T("Wiederholung: ")+IntegrationJson.Text(read,"repeat_state"),L.T("Wiederholung gelesen"));}
            if(op=="like"){var item=IntegrationJson.Get(state,"item");string uri=IntegrationJson.Text(item,"uri");if(!System.Text.RegularExpressions.Regex.IsMatch(uri,@"^spotify:track:[A-Za-z0-9]{22}$"))throw new InvalidOperationException(L.T("Aktuell kein speicherbarer Musiktitel."));api.Request("PUT","/me/library?uris="+Uri.EscapeDataString(uri),null,token);return AddonResult.Of(AddonResultCode.Succeeded,L.T("Speichern von Spotify bestätigt: ")+IntegrationJson.Text(item,"name"));}throw new InvalidOperationException(L.T("Unbekannte Spotify-Aktion."));
        }
    }
}
